import Header from '@/components/Header';
import StorySection from '@/components/StorySection';
import WhatsAppFloat from '@/components/WhatsAppFloat';

// Datos del Menú (Pizzas)
const PIZZAS = [
  {
    id: 'margherita',
    title: 'Margherita Clásica',
    price: 'Q75',
    description: 'Salsa de tomate artesanal, mozzarella fresca, albahaca y un toque de aceite de oliva virgen extra.',
    image: '/images/pizza-margherita.jpg',
  },
  {
    id: 'pepperoni',
    title: 'Pepperoni & Miel Picante',
    price: 'Q85',
    description: 'Mozzarella, pepperoni de primera calidad y un hilo de nuestra miel infusionada con chiles habaneros.',
    image: '/images/pizza-pepperoni.jpg',
  },
  {
    id: 'cuatro-quesos',
    title: 'Cuatro Quesos',
    price: 'Q90',
    description: 'Base blanca con mozzarella, gorgonzola, provolone ahumado y parmesano madurado.',
    image: '/images/pizza-quesos.jpg',
  },
];

// Datos de Postres
const POSTRES = [
  {
    id: 'tiramisu',
    title: 'Tiramisú de la Casa',
    price: 'Q35',
    description: 'Bizcocho bañado en café espresso, crema de mascarpone y cacao en polvo.',
    image: '/images/postre-tiramisu.jpg',
  },
];

export default function HomePage() {
  return (
    <>
      <Header />

      <main>
        {/* 1. HERO SECTION */}
        <section className="hero">
          <video
            className="hero-video"
            autoPlay
            muted
            loop
            playsInline
            poster="/images/masa-hero-poster.jpg"
          >
            <source src="/videos/masa-hero.mp4" type="video/mp4" />
          </video>
          <div className="hero-overlay" />
          <div className="hero-content">
            <p className="label">Pizzería Artesanal</p>
            <h1>CasiPizza</h1>
            <p className="hero-lead">
              Masa de lenta fermentación horneada al punto perfecto.
            </p>
            <div className="hero-actions">
              <a
                href="https://wa.me/50230883119?text=Hola%2C%20quiero%20hacer%20un%20pedido"
                className="cta-button"
                target="_blank"
                rel="noopener noreferrer"
              >
                Pedir por WhatsApp
              </a>
              <a href="#menu" className="cta-button secondary">
                Ver Menú
              </a>
            </div>
          </div>
        </section>

        {/* 2. SECCIÓN HISTORIA */}
        <StorySection />

        {/* 3. SECCIÓN MENÚ */}
        <section id="menu" className="section section-menu">
          <div className="container">
            <p className="label">Especialidades</p>
            <h2>Nuestras Pizzas</h2>
            <p className="section-context">
              Todas nuestras pizzas están elaboradas con masa fermentada por +48 horas.
            </p>

            {/* Grid de Pizzas */}
            <div className="menu-grid">
              {PIZZAS.map((pizza) => (
                <article key={pizza.id} className="pizza-card">
                  <div className="pizza-card-gallery media-gallery">
                    <img
                      src={pizza.image}
                      alt={pizza.title}
                      loading="lazy"
                      style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                    />
                  </div>
                  <div className="pizza-card-top">
                    <h3>{pizza.title}</h3>
                    <span className="price">{pizza.price}</span>
                  </div>
                  <p>{pizza.description}</p>
                  <a
                    href={`https://wa.me/50230883119?text=Hola%2C%20quiero%20pedir%20la%20pizza%20${encodeURIComponent(pizza.title)}`}
                    className="card-cta-button"
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    Pedir esta pizza <span>→</span>
                  </a>
                </article>
              ))}
            </div>

            {/* Tarjeta de Postres (Diseño Horizontal) */}
            <p className="label postre-label">Para Cerrar</p>
            <div className="menu-grid">
              {POSTRES.map((postre) => (
                <article key={postre.id} className="postre-card">
                  <img
                    src={postre.image}
                    alt={postre.title}
                    className="pizza-card-image"
                    loading="lazy"
                  />
                  <div className="postre-card-content">
                    <div className="pizza-card-top">
                      <h3>{postre.title}</h3>
                      <span className="price">{postre.price}</span>
                    </div>
                    <p>{postre.description}</p>
                    <a
                      href={`https://wa.me/50230883119?text=Hola%2C%20quiero%20pedir%20el%20postre%20${encodeURIComponent(postre.title)}`}
                      className="card-cta-button"
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      Agregar postre <span>→</span>
                    </a>
                  </div>
                </article>
              ))}
            </div>

            <div className="menu-footer-cta">
              <a
                href="https://wa.me/50230883119?text=Hola%2C%20quiero%20ver%20el%20men%C3%BA%20completo"
                className="cta-button"
                target="_blank"
                rel="noopener noreferrer"
              >
                Hacer pedido personalizado
              </a>
            </div>
          </div>
        </section>

        {/* 4. SECCIÓN HORARIOS */}
        <section id="horarios" className="section section-hours">
          <div className="container">
            <p className="label">Te esperamos</p>
            <h2>Horarios de Atención</h2>
            <p className="hours-days">Viernes, Sábado y Domingo</p>
            <p className="hours-time">5:00 PM – 10:30 PM</p>
            <p className="section-context hours-note">
              Preparamos una cantidad limitada de masas por día para garantizar la máxima calidad. ¡Haz tu pedido con tiempo!
            </p>
            <a
              href="https://wa.me/50230883119?text=Hola%2C%20quiero%20reservar%20mi%20pedido"
              className="cta-button"
              target="_blank"
              rel="noopener noreferrer"
            >
              Reservar mi pedido
            </a>
          </div>
        </section>
      </main>

      {/* 5. FOOTER */}
      <footer className="footer">
        <div className="container footer-inner">
          <p className="logo">CasiPizza</p>
          <address>Guatemala • Entregas a domicilio y para llevar</address>
          <a
            href="https://www.tiktok.com/@casipizza"
            className="footer-tiktok-link"
            target="_blank"
            rel="noopener noreferrer"
          >
            Síguenos en TikTok
          </a>
        </div>
      </footer>

      {/* Botón Flotante WhatsApp */}
      <WhatsAppFloat />
    </>
  );
}